import"chrome://resources/ash/common/cr_elements/cr_button/cr_button.js";import{BaseSetupPageElement,CANCEL_SETUP_EVENT,NEXT_PAGE_EVENT}from"./base_setup_page.js";import{CloudUploadBrowserProxy}from"./cloud_upload_browser_proxy.js";import{getTemplate}from"./sign_in_page.html.js";export class SignInPageElement extends BaseSetupPageElement{get proxy(){return CloudUploadBrowserProxy.getInstance()}connectedCallback(){super.connectedCallback();this.innerHTML=getTemplate();const connectButton=this.querySelector(".action-button");const cancelButton=this.querySelector(".cancel-button");connectButton.addEventListener("click",(()=>this.onConnectButtonClick()));cancelButton.addEventListener("click",(()=>this.onCancelButtonClick()))}async onConnectButtonClick(){const{success:signInSuccess}=await this.proxy.handler.signInToOneDrive();if(signInSuccess){this.dispatchEvent(new CustomEvent(NEXT_PAGE_EVENT,{bubbles:true,composed:true}))}else{const errorMessage=this.querySelector("#error-message");errorMessage.toggleAttribute("hidden",false);const contentElement=this.shadowRoot.querySelector("#content");contentElement.scrollTop=0;this.updateContentFade(contentElement)}}onCancelButtonClick(){this.dispatchEvent(new CustomEvent(CANCEL_SETUP_EVENT,{bubbles:true,composed:true}))}}customElements.define("sign-in-page",SignInPageElement);